// Finds the first row that hasn't been drafted or flagged yet -- blank status or 'Queued'
// both count. A row marked 'Drafted' or 'Needs Review' is skipped, so a flagged row never
// blocks every row behind it from being tried the following week.
const rows = $input.all();

const next = rows.find(r => {
  const status = String(r.json.status || '').trim().toLowerCase();
  return status === '' || status === 'queued';
});

const content = next ? String(next.json.content || '').trim() : '';

return [{ json: {
  has_content: !!next && content.length > 0,
  row_number: next ? next.json.row_number : null,
  content,
  practice_area: next ? String(next.json.practice_area || '').trim() : '',
} }];

// Reads firm config from n8n Variables and constructs the Claude API request.
// Required variables: FIRM_NAME, FIRM_EMAIL, FIRM_FROM_EMAIL
const FIRM_NAME       = $vars.FIRM_NAME;
const FIRM_EMAIL      = $vars.FIRM_EMAIL;
const FIRM_FROM_EMAIL = $vars.FIRM_FROM_EMAIL;
const CTA_URL         = $vars.FIRM_GBP_CTA_URL || '';
const CTA_TYPE        = $vars.FIRM_GBP_CTA_TYPE || 'LEARN_MORE';

if (!FIRM_NAME)       throw new Error('FIRM_NAME n8n Variable is not set. Go to Settings → Variables and add it.');
if (!FIRM_EMAIL)      throw new Error('FIRM_EMAIL n8n Variable is not set. Go to Settings → Variables and add it.');
if (!FIRM_FROM_EMAIL) throw new Error('FIRM_FROM_EMAIL n8n Variable is not set. Go to Settings → Variables and add it (can be the same as FIRM_EMAIL).');

const item = $input.first().json;
const practiceArea = item.practice_area || 'General practice';

const prompt = `You are a marketing copywriter for ${FIRM_NAME}, a law firm, writing a single Google Business Profile post. Repurpose the raw content below into ONE ready-to-publish post.

Rules you must follow — no exceptions:
- Marketing copy only. No legal advice, legal opinions, case law citations, statutory references, or anything that constitutes legal counsel.
- No client names, case numbers, opposing party names, specific dollar amounts, or any detail that could identify a specific client or matter.
- Maximum 1,500 characters (Google Business Profile's hard limit) — aim for 500-900 for readability.
- Plain language, warm and professional, written for a prospective client doing a local search, not a lawyer.
- End with a short, clear call to action (e.g. "Call us today" or "Schedule a consultation").

Practice area: ${practiceArea}

Raw content:
${item.content}

Return ONLY a valid JSON object — no markdown fences, no preamble. Keys required:
- gbp_post: the post text described above
- is_marketing_safe: true

If producing safe copy is impossible without legal advice or identifying details, return only: {"is_marketing_safe": false, "safety_note": "brief reason"}`;

return [{ json: {
  ...item,
  firm_name: FIRM_NAME,
  firm_email: FIRM_EMAIL,
  firm_from_email: FIRM_FROM_EMAIL,
  cta_url: CTA_URL,
  cta_type: CTA_TYPE,
  claude_request: {
    model: 'claude-sonnet-4-6',
    max_tokens: 800,
    messages: [{ role: 'user', content: prompt }],
  },
} }];

// Parses Claude's JSON response and runs an independent post-hoc keyword scan -- Claude's
// self-report is Layer 1, this scan is Layer 2. is_marketing_safe is true only if both pass.
// References 'Build GBP Post Prompt' for the queue row's metadata.
const prep = $('Build GBP Post Prompt').item.json;

const rawResponse = $input.first().json;
const rawText = (rawResponse.content && rawResponse.content[0] && rawResponse.content[0].text)
  ? rawResponse.content[0].text.trim()
  : '';

if (!rawText) {
  throw new Error('Claude API returned an empty response. Check the Anthropic API key, usage quota, and rate limits at console.anthropic.com.');
}

let parsed;
try {
  const cleaned = rawText.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '');
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Claude did not return valid JSON. Raw response: ' + rawText.slice(0, 400));
}

function flaggedResult(reason) {
  return [{ json: {
    ...prep,
    is_marketing_safe: false,
    safety_note: reason,
    gbp_post: '',
    email_subject: 'GBP Auto-Poster — flagged for human review',
    email_body: [
      "This week's Google Business Profile post was flagged and NOT published.",
      '',
      'Reason: ' + reason,
      '',
      'Original content (row ' + prep.row_number + " in the Content Queue sheet):",
      prep.content,
      '',
      "Edit the row and reset its status to blank so it's picked up again next week, or replace it with different content.",
    ].join('\n'),
  } }];
}

if (parsed.is_marketing_safe === false) {
  return flaggedResult(parsed.safety_note || 'Claude flagged this content as unsafe to repurpose.');
}

let gbp_post = String(parsed.gbp_post || '').trim();

// Post-hoc keyword scan -- catches legal language that slipped past Claude's self-check.
const UNSAFE_RE = /\b(attorney.client|work.product|privileged|legal.advice|legal.opinion|you should|we advise|we recommend|our recommendation|pursuant to|under\s+[§\d]|case law|statute|court held|court ruled|ruling)\b/i;

if (!gbp_post) return flaggedResult('Claude returned an empty post.');
if (UNSAFE_RE.test(gbp_post)) return flaggedResult('Post-hoc scan found legal-sounding language in the generated post.');

// Google Business Profile hard-limits posts to 1,500 characters -- truncate at a word boundary
// rather than let the publish call fail outright if Claude ran long despite instructions.
const LIMIT = 1500;
let truncated = false;
if (gbp_post.length > LIMIT) {
  gbp_post = gbp_post.slice(0, LIMIT - 1).replace(/\s+\S*$/, '') + '…';
  truncated = true;
}

return [{ json: {
  ...prep,
  is_marketing_safe: true,
  gbp_post,
  truncated,
  char_count: gbp_post.length,
  email_subject: 'Google Business Profile post ready to paste — ' + new Date().toLocaleDateString('en-US'),
  email_body: (() => {
    const lines = [
      "This week's Google Business Profile post is ready — copy it in below.",
      '',
      'POST TEXT (' + gbp_post.length + ' / 1,500 chars)' + (truncated ? ' — truncated to fit the limit, review recommended' : ''),
      '─'.repeat(60),
      gbp_post,
      '─'.repeat(60),
    ];
    if (prep.cta_url) {
      lines.push('', 'Suggested call-to-action button: ' + (prep.cta_type || 'LEARN_MORE') + ' → ' + prep.cta_url);
    }
    lines.push('', 'Paste this into Google Business Profile: ' + ($vars.FIRM_GBP_DASHBOARD_URL || 'business.google.com → your profile → Add update'));
    return lines.join('\n');
  })(),
} }];
